import argparse
import os
from pathlib import Path
import shlex
import subprocess
import tempfile


def write_bus_fixture(root, directory):
    """Compile the host-safe production sections without the ESP peripheral drivers."""
    wled = root / "wled00"
    sections = (
        (wled / "bus_wrapper.h", "enum LegacyField", "class PixelBusAllocator"),
        (wled / "colors.cpp", "uint32_t IRAM_ATTR color_fade(", "\n}"),
        (wled / "colors.cpp", "namespace {\nstruct GammaCurve", "uint32_t WLEDGamma::inverseGamma32"),
        (wled / "colors.cpp", "uint32_t WLEDGamma::inverseGamma32", "\n}"),
        (wled / "src" / "WLEDpixelBus" / "WLEDpixelBus.cpp",
         "namespace WLEDpixelBus {", "// create a 1-wire digital bus"),
        (wled / "bus_manager.cpp", "static ColorOrderMap _colorOrderMap", "#ifdef ESP8266\n  // 1 MHz clock"),
        (wled / "bus_manager.cpp", "void BusManager::show()", "uint32_t BusManager::getPixelColor"),
        (wled / "bus_manager.cpp", "void BusManager::initializeABL()", "// PixelBusAllocator channel tracking"),
        (wled / "bus_manager.cpp", "// Bus static member definition", None),
    )
    with (directory / "bus_production.inc").open("w", encoding="utf-8") as fixture:
        for path, first, last in sections:
            text = path.read_text(encoding="utf-8-sig")
            start = text.index(first)
            end = text.index(last, start) if last else len(text)
            if last == "\n}":
                end += len(last)
            line = text.count("\n", 0, start) + 1
            fixture.write(f'\n#line {line} "{path.as_posix()}"\n')
            fixture.write(text[start:end])
            if first == "namespace WLEDpixelBus {":
                fixture.write("\n}\n")


def main():
    """Keep build output temporary; CXX may name a compiler or 'zig c++'."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--examples", action="store_true")
    parser.add_argument("--integration", action="store_true", help="Run the WLED state/KNX packet and digital Bus checks")
    parser.add_argument("--unit-only", action="store_true", help="Run only focused command/conversion checks")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    compiler = shlex.split(os.environ.get("CXX", "c++"), posix=os.name != "nt")
    compiler = [part.strip('"') for part in compiler]
    with tempfile.TemporaryDirectory(prefix="wled-knx-") as temporary:
        directory = Path(temporary)
        exe = directory / ("knx-control.exe" if os.name == "nt" else "knx-control")
        integration = ["integration_test.cpp", "bus_output_test.cpp"]
        sources = ["control_test.cpp", *integration]
        if args.examples or args.unit_only:
            sources = ["control_test.cpp"]
        elif args.integration:
            sources = integration
        if "bus_output_test.cpp" in sources:
            write_bus_fixture(root, directory)
        for source in sources:
            subprocess.run(compiler + ["-std=c++17", "-O2", "-Wall", "-Wextra", "-Werror",
                           "-Wno-unused-function", "-Wno-unused-parameter", "-DKNX_UM_SUPPRESS_WARN",
                           "-I", str(root / "test/knx_control/stubs"), "-I", str(directory),
                           str(root / "test/knx_control" / source), "-o", str(exe)],
                           check=True, cwd=root)
            subprocess.run([str(exe)] + (["--examples"] if args.examples else []), check=True)


if __name__ == "__main__":
    main()
